import{_ as t,o as a,c as o,a2 as d}from"./chunks/framework.BGlkWkwp.js";const m=JSON.parse('{"title":"Stack","description":"","frontmatter":{},"headers":[],"relativePath":"components/stack.md","filePath":"components/stack.md"}'),r={name:"components/stack.md"};function n(s,e,c,i,h,l){return a(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="stack" tabindex="-1">Stack <a class="header-anchor" href="#stack" aria-label="Permalink to &quot;Stack&quot;">​</a></h1><p>Stack is the vertical layout. It is the only container that holds the distance between the things stacked in it, and it has no outline or surface of its own.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it for anything that runs from top to bottom. Choose the gap by the relation between the children: 0 for a title and its caption, sm within one group, md between different elements, lg between topics and xl between the sections of a long page. The steps 2xs and xs belong inside components. For side by side, use <a href="./row">Row</a>; for columns, <a href="./grid">Grid</a>.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>gap</code></td><td>required</td><td><code>0</code>, <code>2xs</code>, <code>xs</code>, <code>sm</code>, <code>md</code>, <code>lg</code>, <code>xl</code> or <code>2xl</code></td></tr><tr><td><code>align</code></td><td><code>stretch</code></td><td><code>start</code> keeps each child at its own width</td></tr><tr><td><code>children</code></td><td>required</td><td>The content</td></tr></tbody></table><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>Stack has no height, padding or line. The gap is a <code>--kata-gap-*</code> step and runs between the untrimmed line boxes of the children, so text in a stack is apart by the gap plus its leading. Controls stacked directly are at least md apart.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/stack/" title="Stack" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/stack/" target="_blank" rel="noopener">Stack</a></figcaption></figure>',10)])])}const u=t(r,[["render",n]]);export{m as __pageData,u as default};
